1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	
4	<head>
5	  <meta charset="UTF-8">
6	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
7	  <title>JSON 数据编辑器</title>
8	  <style>
9	    :root {
10	      --bg: #0d1117;
11	      --surface: #161b22;
12	      --border: #30363d;
13	      --text: #c9d1d9;
14	      --text-muted: #8b949e;
15	      --accent: #58a6ff;
16	      --danger: #f85149;
17	      --success: #3fb950;
18	      --warning: #d2991d;
19	      --row-hover: #1c2129;
20	      --cell-edit: #1f2a37;
21	      --cell-computed: #1a1e26;
22	    }
23	
24	    * {
25	      margin: 0;
26	      padding: 0;
27	      box-sizing: border-box;
28	    }
29	
30	    body {
31	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
32	      background: var(--bg);
33	      color: var(--text);
34	      min-height: 100vh;
35	      line-height: 1.5;
36	    }
37	
38	    /* ── header ── */
39	    .header {
40	      background: var(--surface);
41	      border-bottom: 1px solid var(--border);
42	      padding: 16px 24px;
43	      display: flex;
44	      align-items: center;
45	      gap: 16px;
46	      flex-wrap: wrap;
47	      position: sticky;
48	      top: 0;
49	      z-index: 10;
50	    }
51	
52	    .header h1 {
53	      font-size: 18px;
54	      font-weight: 600;
55	      white-space: nowrap;
56	    }
57	
58	    .header .sep {
59	      flex: 1;
60	    }
61	
62	    /* ── toolbar ── */
63	    .toolbar {
64	      display: flex;
65	      gap: 8px;
66	      flex-wrap: wrap;
67	      align-items: center;
68	    }
69	
70	    select,
71	    button,
72	    input[type=text],
73	    input[type=file] {
74	      font-family: inherit;
75	      font-size: 13px;
76	      padding: 6px 12px;
77	      border-radius: 6px;
78	      border: 1px solid var(--border);
79	      background: var(--bg);
80	      color: var(--text);
81	      cursor: pointer;
82	      transition: border-color .15s;
83	    }
84	
85	    select:hover,
86	    button:hover {
87	      border-color: var(--accent);
88	    }
89	
90	    button.primary {
91	      background: #238636;
92	      border-color: #238636;
93	      color: #fff;
94	    }
95	
96	    button.primary:hover {
97	      background: #2ea043;
98	    }
99	
100	    button.danger {
101	      background: #da3633;
102	      border-color: #da3633;
103	      color: #fff;
104	    }
105	
106	    button.danger:hover {
107	      background: #f85149;
108	    }
109	
110	    button:disabled {
111	      opacity: .4;
112	      pointer-events: none;
113	    }
114	
115	    input[type=text] {
116	      cursor: text;
117	      min-width: 180px;
118	    }
119	
120	    input[type=text]:focus {
121	      outline: none;
122	      border-color: var(--accent);
123	    }
124	
125	    .file-label {
126	      cursor: pointer;
127	      padding: 6px 12px;
128	      border-radius: 6px;
129	      border: 1px dashed var(--border);
130	      font-size: 13px;
131	      color: var(--text-muted);
132	      transition: border-color .15s;
133	    }
134	
135	    .file-label:hover {
136	      border-color: var(--accent);
137	      color: var(--accent);
138	    }
139	
140	    .file-label input {
141	      display: none;
142	    }
143	
144	    /* ── table area ── */
145	    .table-wrap {
146	      overflow: auto;
147	      max-height: calc(100vh - 100px);
148	      margin: 8px;
149	      border-radius: 8px;
150	      border: 1px solid var(--border);
151	    }
152	
153	    table {
154	      width: 100%;
155	      border-collapse: collapse;
156	      font-size: 13px;
157	    }
158	
159	    thead {
160	      position: sticky;
161	      top: 0;
162	      z-index: 5;
163	    }
164	
165	    th {
166	      background: var(--surface);
167	      padding: 10px 12px;
168	      text-align: left;
169	      font-weight: 600;
170	      white-space: nowrap;
171	      border-bottom: 2px solid var(--border);
172	      cursor: pointer;
173	      user-select: none;
174	      color: var(--text-muted);
175	      transition: color .15s;
176	    }
177	
178	    th:hover {
179	      color: var(--accent);
180	    }
181	
182	    th .sort-arrow {
183	      margin-left: 4px;
184	      font-size: 11px;
185	      opacity: .5;
186	    }
187	
188	    th.sort-asc .sort-arrow,
189	    th.sort-desc .sort-arrow {
190	      opacity: 1;
191	      color: var(--accent);
192	    }
193	
194	    th.col-index {
195	      width: 48px;
196	      min-width: 48px;
197	      text-align: center;
198	      cursor: default;
199	      color: var(--text-muted);
200	    }
201	
202	    th.col-computed {
203	      color: #5a6a7e;
204	    }
205	
206	    td {
207	      padding: 8px 12px;
208	      border-bottom: 1px solid var(--border);
209	      white-space: nowrap;
210	      transition: background .1s;
211	    }
212	
213	    tr:hover td {
214	      background: var(--row-hover);
215	    }
216	
217	    /* editable cells */
218	    td.editable {
219	      cursor: text;
220	    }
221	
222	    td.editable:focus-within {
223	      background: var(--cell-edit);
224	      outline: 1px solid var(--accent);
225	      outline-offset: -1px;
226	    }
227	
228	    td.editable input {
229	      background: transparent;
230	      border: none;
231	      color: var(--text);
232	      font: inherit;
233	      width: 100%;
234	      padding: 0;
235	      outline: none;
236	    }
237	
238	    td.editable input:focus {
239	      outline: none;
240	    }
241	
242	    /* computed (read-only) cells */
243	    td.computed {
244	      cursor: default;
245	      color: #8b949e;
246	      font-style: italic;
247	    }
248	
249	    td.computed:hover {
250	      background: var(--cell-computed);
251	    }
252	
253	    /* modified marker */
254	    td.modified {
255	      position: relative;
256	    }
257	
258	    td.modified::after {
259	      content: '';
260	      position: absolute;
261	      top: 2px;
262	      right: 4px;
263	      width: 6px;
264	      height: 6px;
265	      border-radius: 50%;
266	      background: var(--warning);
267	    }
268	
269	    td.col-index {
270	      text-align: center;
271	      color: var(--text-muted);
272	      font-size: 11px;
273	    }
274	
275	    /* ── delete button ── */
276	    .del-btn {
277	      padding: 2px 8px;
278	      font-size: 11px;
279	      border-radius: 4px;
280	      border: 1px solid transparent;
281	      background: transparent;
282	      color: var(--text-muted);
283	      cursor: pointer;
284	      transition: all .15s;
285	    }
286	
287	    .del-btn:hover {
288	      color: var(--danger);
289	      border-color: var(--danger);
290	    }
291	
292	    /* ── empty state ── */
293	    .empty {
294	      text-align: center;
295	      padding: 80px 24px;
296	      color: var(--text-muted);
297	    }
298	
299	    .empty .icon {
300	      font-size: 48px;
301	      margin-bottom: 12px;
302	    }
303	
304	    .empty p {
305	      font-size: 14px;
306	    }
307	
308	    /* ── toast ── */
309	    .toast {
310	      position: fixed;
311	      bottom: 24px;
312	      left: 50%;
313	      transform: translateX(-50%);
314	      background: var(--surface);
315	      border: 1px solid var(--border);
316	      padding: 10px 20px;
317	      border-radius: 8px;
318	      font-size: 13px;
319	      z-index: 100;
320	      animation: toastIn .25s ease;
321	      box-shadow: 0 4px 12px rgba(0, 0, 0, .4);
322	    }
323	
324	    @keyframes toastIn {
325	      from {
326	        opacity: 0;
327	        transform: translateX(-50%) translateY(8px);
328	      }
329	    }
330	
331	    /* ── stats bar ── */
332	    .stats {
333	      background: var(--surface);
334	      border-bottom: 1px solid var(--border);
335	      padding: 6px 24px;
336	      font-size: 12px;
337	      color: var(--text-muted);
338	      display: flex;
339	      gap: 16px;
340	      flex-wrap: wrap;
341	      align-items: center;
342	    }
343	
344	    .stats .dirty {
345	      color: var(--warning);
346	    }
347	
348	    .stats .computed-info {
349	      color: #5a6a7e;
350	    }
351	  </style>
352	</head>
353	
354	<body>
355	
356	  <div class="header">
357	    <h1>📊 JSON 数据编辑器</h1>
358	    <div class="sep"></div>
359	    <div class="toolbar">
360	      <span class="file-label" id="openFileBtn" onclick="openLocalFile()" title="打开本地 JSON 文件">
361	        📂 打开 JSON
362	      </span>
363	      <input type="file" id="fileInput" accept=".json" onchange="loadFile(this)" style="display:none">
364	      <select id="presetSelect" onchange="loadPreset(this.value)">
365	        <option value="">— 快速加载项目数据 —</option>
366	        <optgroup label="LoLM 分路数据">
367	          <option value="lolm/上路.json">上路</option>
368	          <option value="lolm/打野.json">打野</option>
369	          <option value="lolm/中路.json">中路</option>
370	          <option value="lolm/下路.json">下路</option>
371	          <option value="lolm/辅助.json">辅助</option>
372	        </optgroup>
373	        <optgroup label="曙光英雄">
374	          <option value="曙光英雄/曙光英雄.json">曙光英雄</option>
375	        </optgroup>
376	      </select>
377	      <button onclick="addRow()" disabled id="addBtn">＋ 添加行</button>
378	      <button class="primary" onclick="applyChanges()" disabled id="applyBtn" style="opacity:0.4">✏️ 应用修改</button>
379	      <button onclick="undoAll()" disabled id="undoBtn" class="danger" style="display:none">↩ 撤销全部修改</button>
380	    </div>
381	    <div class="toolbar">
382	      <button class="primary" onclick="saveJSON()" disabled id="saveBtn">💾 下载 JSON</button>
383	    </div>
384	  </div>
385	
386	  <div class="stats" id="stats" style="display:none">
387	    <span id="statFile"></span>
388	    <span id="statRows"></span>
389	    <span id="statDirty" class="dirty"></span>
390	    <span id="statComputed" class="computed-info"></span>
391	  </div>
392	
393	  <div class="table-wrap" id="tableWrap">
394	    <div class="empty" id="empty">
395	      <div class="icon">📂</div>
396	      <p>打开一个 JSON 文件开始编辑</p>
397	      <p style="font-size:12px;margin-top:4px;">支持从上方菜单加载项目数据，或拖放 / 选择本地 .json 文件</p>
398	    </div>
399	    <table id="dataTable" style="display:none">
400	      <thead id="tableHead"></thead>
401	      <tbody id="tableBody"></tbody>
402	    </table>
403	  </div>
404	
405	  <script>
406	    // ── state ──
407	    let data = null;           // parsed array of objects
408	    let columns = [];          // detected column keys
409	    let original = null;       // deep copy for undo
410	    let sortKey = null;
411	    let sortDir = 1;
412	    let currentFile = '';
413	    let currentFileHandle = null; // FileSystemFileHandle for direct write-back
414	    let computedFields = {};   // { fieldName: { dependsOn: [], compute: fn } }
415	
416	    // ── computed field definitions ──
417	    // Add more definitions here when needed. The editor auto-detects which ones
418	    // apply based on whether all dependsOn columns exist in the loaded data.
419	    const COMPUTED_DEFS = {
420	      combatPower: {
421	        dependsOn: ['国9战力', '国50战力', '国100战力'],
422	        compute: (row) => (Number(row['国9战力']) || 0) + (Number(row['国50战力']) || 0) + (Number(row['国100战力']) || 0),
423	        hint: '= 国9 + 国50 + 国100'
424	      }
425	    };
426	
427	    // ── helpers ──
428	    function $(id) { return document.getElementById(id); }
429	
430	    function toast(msg) {
431	      const el = Object.assign(document.createElement('div'), { className: 'toast', textContent: msg });
432	      document.body.appendChild(el);
433	      setTimeout(() => el.remove(), 2000);
434	    }
435	
436	    function detectColumns(arr) {
437	      if (!arr || !arr.length) return [];
438	      const keys = new Set();
439	      arr.forEach(obj => Object.keys(obj).forEach(k => keys.add(k)));
440	      return Array.from(keys);
441	    }
442	
443	    function normalizeValue(val) {
444	      if (val === null || val === undefined) return '';
445	      if (typeof val === 'object') return JSON.stringify(val);
446	      return String(val);
447	    }
448	
449	    // Check which computed fields apply to the current data
450	    function resolveComputedFields() {
451	      computedFields = {};
452	      if (!data || !data.length) return;
453	      const cols = new Set(detectColumns(data));
454	      for (const [field, def] of Object.entries(COMPUTED_DEFS)) {
455	        if (cols.has(field) && def.dependsOn.every(d => cols.has(d))) {
456	          computedFields[field] = def;
457	        }
458	      }
459	    }
460	
461	    // ── render ──
462	    function render() {
463	      resolveComputedFields();
464	
465	      if (!data || !data.length) {
466	        $('dataTable').style.display = 'none';
467	        $('empty').style.display = '';
468	        $('stats').style.display = 'none';
469	        $('saveBtn').disabled = true;
470	        $('addBtn').disabled = true;
471	        $('applyBtn').disabled = true;
472	        $('applyBtn').style.opacity = '0.4';
473	        return;
474	      }
475	
476	      $('empty').style.display = 'none';
477	      $('dataTable').style.display = '';
478	      $('saveBtn').disabled = false;
479	      $('addBtn').disabled = false;
480	      $('applyBtn').disabled = true;
481	      $('applyBtn').style.opacity = '0.4';
482	      $('stats').style.display = 'flex';
483	
484	      columns = detectColumns(data);
485	
486	      // sort
487	      let sorted = [...data];
488	      if (sortKey && columns.includes(sortKey)) {
489	        sorted.sort((a, b) => {
490	          let va = a[sortKey], vb = b[sortKey];
491	          let na = parseFloat(va), nb = parseFloat(vb);
492	          if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
493	          return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
494	        });
495	      }
496	
497	      // head
498	      let headHtml = '<tr><th class="col-index">#</th>';
499	      columns.forEach(col => {
500	        let cls = '';
501	        if (sortKey === col) cls = sortDir === 1 ? 'sort-asc' : 'sort-desc';
502	        if (computedFields[col]) cls += ' col-computed';
503	        const label = computedFields[col] ? col + ' 🔒' : col;
504	        headHtml += `<th class="${cls}" onclick="sortBy('${esc(col)}')">${label}<span class="sort-arrow">${sortKey === col ? (sortDir === 1 ? '▲' : '▼') : ''}</span></th>`;
505	      });
506	      headHtml += '<th class="col-index" style="cursor:default">✕</th></tr>';
507	      $('tableHead').innerHTML = headHtml;
508	
509	      // body
510	      let bodyHtml = '';
511	      sorted.forEach((row, sortedIdx) => {
512	        const dataIdx = data.indexOf(row);
513	        bodyHtml += `<tr>`;
514	        bodyHtml += `<td class="col-index">${sortedIdx + 1}</td>`;
515	        columns.forEach(col => {
516	          if (computedFields[col]) {
517	            // ── computed cell (read-only) ──
518	            let val = normalizeValue(row[col]);
519	            bodyHtml += `<td class="computed">${val}</td>`;
520	          } else {
521	            // ── editable cell ──
522	            let val = normalizeValue(row[col]);
523	            // Compare only this cell's value, not the whole row
524	            let origVal = original && dataIdx >= 0 && dataIdx < original.length
525	              ? original[dataIdx][col] : undefined;
526	            let isMod = origVal !== undefined && String(row[col] ?? '') !== String(origVal ?? '');
527	            bodyHtml += `<td class="editable${isMod ? ' modified' : ''}">`
528	              + `<input value="${val.replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}"`
529	              + ` data-col="${esc(col)}" data-sorted-idx="${sortedIdx}" data-original="${esc(val)}"`
530	              + ` oninput="markDirty(this)" onfocus="this.select()">`
531	              + `</td>`;
532	          }
533	        });
534	        bodyHtml += `<td><button class="del-btn" onclick="deleteRow(${sortedIdx})" title="删除此行">✕</button></td>`;
535	        bodyHtml += `</tr>`;
536	      });
537	      $('tableBody').innerHTML = bodyHtml;
538	
539	      // stats
540	      $('statFile').textContent = '📄 ' + (currentFile || '未命名数据');
541	      $('statRows').textContent = `📋 ${data.length} 行 × ${columns.length} 列`;
542	      $('statDirty').textContent = '💡 编辑后点击「✏️ 应用修改」保存到数据模型';
543	
544	      // Undo button: show if original snapshot exists
545	      if (original) {
546	        $('undoBtn').style.display = '';
547	        $('undoBtn').disabled = false;
548	      } else {
549	        $('undoBtn').style.display = 'none';
550	      }
551	
552	      let compKeys = Object.keys(computedFields);
553	      $('statComputed').textContent = compKeys.length ? `🔒 自动计算: ${compKeys.join(', ')}` : '';
554	    }
555	
556	    function esc(s) {
557	      return s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '&quot;');
558	    }
559	
560	    // ── edit helpers ──
561	    function startEdit(td) {
562	      const input = td.querySelector('input');
563	      if (!input || document.activeElement === input) return;
564	      input.focus();
565	    }
566	
567	    // Mark an input (and its td) as dirty when the user types
568	    function markDirty(input) {
569	      const td = input.closest('td');
570	      if (td) td.classList.add('modified');
571	      updateSaveState();
572	    }
573	
574	    // Check if any input differs from its data-original value
575	    function hasUnsavedChanges() {
576	      const inputs = $('tableBody').querySelectorAll('input');
577	      for (const inp of inputs) {
578	        if (inp.dataset.col && inp.value.trim() !== (inp.dataset.original || '')) return true;
579	      }
580	      return false;
581	    }
582	
583	    // Enable/disable save-related UI based on dirty state
584	    function updateSaveState() {
585	      const dirty = hasUnsavedChanges();
586	      console.log('[SAVE-STATE] dirty:', dirty, 'applyBtn disabled:', !dirty);
587	      $('applyBtn').disabled = !dirty;
588	      $('applyBtn').style.opacity = dirty ? '1' : '0.4';
589	    }
590	
591	    // Read all inputs from DOM, write to data, recalc, re-render
592	    function applyChanges() {
593	      if (!data) return;
594	      const inputs = $('tableBody').querySelectorAll('input');
595	      let changed = 0;
596	
597	      if (!original) original = JSON.parse(JSON.stringify(data));
598	
599	      const sorted = getSortedData();
600	
601	      inputs.forEach(input => {
602	        const col = input.dataset.col;
603	        const sortedIdx = parseInt(input.dataset.sortedIdx);
604	        const newVal = input.value.trim();
605	        const oldVal = (input.dataset.original || '').trim();
606	
607	        if (!col || newVal === oldVal) return;
608	
609	        // auto-detect number
610	        let val = newVal;
611	        if (val !== '' && !isNaN(val) && !/^0\d/.test(val)) val = Number(val);
612	
613	        // Map sortedIdx → data[]
614	        if (sortedIdx >= 0 && sortedIdx < sorted.length) {
615	          const row = sorted[sortedIdx];
616	          const dataIdx = data.indexOf(row);
617	          if (dataIdx >= 0) {
618	            data[dataIdx][col] = val;
619	            recalcRow(data[dataIdx]);
620	            changed++;
621	          }
622	        }
623	      });
624	
625	      if (changed > 0) {
626	        recalcAll(); // ensure cross-row computed consistency
627	        render();
628	        toast(`已应用 ${changed} 个修改`);
629	      } else {
630	        toast('没有需要保存的修改');
631	      }
632	    }
633	
634	    // Recalculate all computed fields for a single row
635	    function recalcRow(row) {
636	      for (const [field, def] of Object.entries(computedFields)) {
637	        row[field] = def.compute(row);
638	      }
639	    }
640	
641	    // Recalculate all computed fields for all rows (e.g. after initial load)
642	    function recalcAll() {
643	      if (!data) return;
644	      resolveComputedFields();
645	      data.forEach(row => recalcRow(row));
646	    }
647	
648	    // ── sort ──
649	    function getSortedData() {
650	      if (!data) return [];
651	      let sorted = [...data];
652	      if (sortKey && columns.includes(sortKey)) {
653	        sorted.sort((a, b) => {
654	          let va = a[sortKey], vb = b[sortKey];
655	          let na = parseFloat(va), nb = parseFloat(vb);
656	          if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
657	          return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
658	        });
659	      }
660	      return sorted;
661	    }
662	
663	    function sortBy(col) {
664	      if (hasUnsavedChanges()) {
