907	function syncURL() {
908	  const params = new URLSearchParams();
909	  if (gameConfig) params.set("game", gameConfig.gameId);
910	  if (currentMethod) params.set("method", currentMethod);
911	  if (currentView) params.set("view", currentView);
912	  if (currentLane) params.set("lane", currentLane);
913	  if (currentViewMode !== "table") params.set("viewmode", currentViewMode);
914	  const newUrl = window.location.pathname + "?" + params.toString();
915	  if (window.location.search !== "?" + params.toString()) {
916	    window.history.replaceState(null, "", newUrl);
917	  }
918	}
