923	async function init() {
924	  // Parse URL params
925	  const params = new URLSearchParams(window.location.search);
926	  const gameId = params.get("game") || "lolm";
927	  if (params.get("viewmode") === "grid") currentViewMode = "grid";
928	
929	  await switchGame(gameId);
930	}
931	
932	// Auto-start
933	document.addEventListener("DOMContentLoaded", init);
