14	function mean(a) { return a.reduce((s,v)=>s+v,0)/a.length; }
15	function std(a) { const m=mean(a); return Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/a.length); }
16	function minmax(arr) { const lo=Math.min(...arr), hi=Math.max(...arr); return arr.map(v=>(v-lo)/(hi-lo||1)); }
17	function cv(arr) { return std(arr)/Math.abs(mean(arr)); }
18	
19	function spearman(x, y) {
20	  const n = x.length;
21	  const rank = arr => { const idx = arr.map((_,i)=>i).sort((a,b)=>arr[a]-arr[b]); const r=Array(n); idx.forEach((v,i)=>r[v]=i+1); return r; };
22	  const rx = rank(x), ry = rank(y);
23	  const mx = mean(rx), my = mean(ry);
24	  const num = rx.reduce((s,v,i)=>s+(v-mx)*(ry[i]-my),0);
25	  const den = Math.sqrt(rx.reduce((s,v)=>s+(v-mx)**2,0) * ry.reduce((s,v)=>s+(v-my)**2,0));
26	  return num/(den||1);
27	}
